private boolean assignableFrom(Collection<Class<? extends Detector>> excludeDetectors, Class<? extends Detector> d) {
    for (Class<? extends Detector> e : excludeDetectors) {
        if (e.isAssignableFrom(d)) {
            return true;
        }
    }
    return false;
}
